import{_ as e}from"./chunks/CourseWebArticle.vue_vue_type_style_index_0_lang.8827500c.js";import{o as d,c as s,H as n,l as a}from"./chunks/framework.ac6a668e.js";const l=`<section data-web-part="0"><div dir="auto" data-markdown-text-style="assistant-message" style="--markdown-link-color: currentColor;" data-web-style="s0"><div data-dil-source-message-id="651b7f0b-2165-4e1c-bcc9-a8c954000ac5" data-web-style="s1"><div data-web-style="s1"><div hidden="" data-web-style="s2"></div><div style="--puik-portal-zoom: 1;" data-web-style="s1"><div dir="auto" data-d-inline-reveal="" data-d-direction="col" data-dil-message-id="651b7f0b-2165-4e1c-bcc9-a8c954000ac5" data-web-style="s3"><h1 data-d-text-flow="" data-d-component="title" data-d-size="xl" data-d-weight="semibold" data-web-style="s4">📘 第 07 篇：大模型的能力边界——上下文窗口、幻觉与推理限制</h1><div data-d-align="center" data-d-component="row" data-d-direction="row" data-d-wrap="wrap" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s5"><div data-color="success" data-size="sm" data-pill="" data-variant="soft" data-d-component="badge" data-d-weight="medium" data-web-style="s6">第 07 / 40 篇</div><p data-d-text-flow="" data-d-component="text" data-d-size="xs" style="color: var(--color-text-secondary);" data-web-style="s7">第一阶段：AI 与大模型基础 · 收官篇</p><p data-d-text-flow="" data-d-component="text" data-d-size="xs" style="color: var(--color-text-secondary);" data-web-style="s7"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-d-inline="" style="display: inline-block; vertical-align: calc(0.5cap - 0.5em);" data-web-style="s8" viewBox="0 0 24 24"><path d="M12 4C7.58172 4 4 7.58172 4 12C4 16.4183 7.58172 20 12 20C16.4183 20 20 16.4183 20 12C20 7.58172 16.4183 4 12 4ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12ZM12 6C12.5523 6 13 6.44772 13 7V12C13 12.2652 12.8946 12.5196 12.7071 12.7071L10.2071 15.2071C9.81658 15.5976 9.18342 15.5976 8.79289 15.2071C8.40237 14.8166 8.40237 14.1834 8.79289 13.7929L11 11.5858V7C11 6.44772 11.4477 6 12 6Z" fill="currentColor" data-web-style="s9"></path></svg> 阅读约 15 分钟</p></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">前六篇，我们已经了解了大语言模型如何将文字转换成 Token、利用 Transformer 处理上下文、通过训练获得能力，以及如何通过 Prefill、Decode 和 KV Cache 生成回答。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">但一个能够流畅回答问题的模型，是否就意味着它能够准确回答所有问题？</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">答案是：<span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">不能。</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">例如：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0); gap: calc(var(--spacing, 0.25rem) * 0);" data-web-style="s12"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">为什么 ChatGPT 明明支持很长的上下文，却可能忘记文档中间的信息？</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">为什么 AI 有时候会编造不存在的 API？</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">为什么 Temperature 设置为 0，回答仍然可能出错？</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">为什么一道看似简单的数学题，大模型也可能算错？</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">如何在工程上降低这些问题带来的风险？</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s10">今天我们会从模型原理、交互实验和 TypeScript 工程实践三个角度理解这些问题。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">一、上下文窗口：模型一次能看到多少内容？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">Context Window（上下文窗口）是模型单次推理能够处理的上下文容量限制，通常以 Token 为单位衡量。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">假设一个模型支持 128K Tokens 的上下文窗口。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">这并不意味着你可以输入 128K Tokens 的问题，再让它无限输出回答。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">在常见的共享窗口设计中：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s20"><span data-web-style="s21"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>T</mi><mtext>input</mtext></msub><mo>+</mo><msub><mi>T</mi><mtext>output</mtext></msub><mo>≤</mo><msub><mi>T</mi><mtext>context</mtext></msub></mrow><annotation encoding="application/x-tex">T_{\\text{input}}+T_{\\text{output}}\\leq T_{\\text{context}}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.9694em; vertical-align: -0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3175em;"><span style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">input</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.9694em; vertical-align: -0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.2806em;"><span style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">output</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.2806em;"><span style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">context</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span></span></span></span></span></span></span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">还可能受到独立的最大输出长度限制。不同模型 API 的计算规则有所差异。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s22">1.1 上下文窗口包含什么？</h3><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s23"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">上下文窗口容量示意</span></p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s25"><div data-d-clip="true" data-d-component="row" data-d-direction="row" data-d-has-height="" style="border-radius: var(--radius-md); gap: 1px; height: 44px;" data-web-style="s26"><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" data-d-justify="center" style="--smoothing-background-color: #64748b; background-color: rgb(100, 116, 139); flex: 12 1 0%;" data-web-style="s27"><p data-d-text-flow="" data-d-component="text" data-d-size="2xs" data-d-weight="medium" style="color: rgb(255, 255, 255);" data-web-style="s28">系统提示</p></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" data-d-justify="center" style="--smoothing-background-color: #2563eb; background-color: rgb(37, 99, 235); flex: 30 1 0%;" data-web-style="s29"><p data-d-text-flow="" data-d-component="text" data-d-size="2xs" data-d-weight="medium" style="color: rgb(255, 255, 255);" data-web-style="s28">历史消息</p></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" data-d-justify="center" style="--smoothing-background-color: #16a34a; background-color: rgb(22, 163, 74); flex: 38 1 0%;" data-web-style="s30"><p data-d-text-flow="" data-d-component="text" data-d-size="2xs" data-d-weight="medium" style="color: rgb(255, 255, 255);" data-web-style="s28">当前输入</p></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" data-d-justify="center" style="--smoothing-background-color: #d97706; background-color: rgb(217, 119, 6); flex: 20 1 0%;" data-web-style="s31"><p data-d-text-flow="" data-d-component="text" data-d-size="2xs" data-d-weight="medium" style="color: rgb(255, 255, 255);" data-web-style="s28">输出预算</p></div></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s32">比例仅用于演示，不代表真实模型的固定分配。</span></div><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s33">实际请求还可能包含工具结果、检索文档、消息格式开销等内容。</p></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s22">1.2 交互实验：上下文预算</h3><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 3);" data-web-style="s34" data-web-lab="budget" data-web-lab-id="budget"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">128K Token 上下文预算模拟器</span></p><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s35"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s36">聊天历史</p><p data-d-text-flow="" data-d-component="text" data-web-style="s37"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11" data-web-range-label="0" data-web-format="{value}K">40K</span></p></div><input type="range" min="0" max="100" value="40" step="1" aria-label="教程交互参数 1" data-web-range="0" data-web-initial="40" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s35"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s36">检索文档</p><p data-d-text-flow="" data-d-component="text" data-web-style="s37"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11" data-web-range-label="1" data-web-format="{value}K">50K</span></p></div><input type="range" min="0" max="100" value="50" step="1" aria-label="教程交互参数 2" data-web-range="1" data-web-initial="50" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s35"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s36">预留输出</p><p data-d-text-flow="" data-d-component="text" data-web-style="s37"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11" data-web-range-label="2" data-web-format="{value}K">8K</span></p></div><input type="range" min="1" max="32" value="8" step="1" aria-label="教程交互参数 3" data-web-range="2" data-web-initial="8" style="display:block;width:100%;min-width:0;accent-color:var(--vp-c-brand-1);cursor:pointer"><div data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: var(--color-surface-secondary); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s42"><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s35"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-web-style="s36">已规划容量（另含 5K 系统提示）</p><p data-d-text-flow="" data-d-component="text" data-d-weight="medium" data-d-tabular-nums="true" data-web-style="s43" data-web-output="budget">103K / 128K</p></div><div data-d-auto-spacing="" data-d-clip="true" data-d-component="box" data-d-direction="col" data-d-has-height="" style="--smoothing-background-color: var(--color-surface-tertiary); border-radius: 9999px; background-color: var(--color-surface-tertiary); flex-shrink: 0; height: 12px;" data-web-style="s44"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" data-d-has-width="" data-d-has-height="" style="--smoothing-background-color: #16a34a; border-radius: 9999px; background-color: rgb(22, 163, 74); flex-shrink: 0; height: 100%; width: 80.4688%;" data-web-style="s45"></div></div><p data-d-text-flow="" data-d-component="text" data-d-size="sm" data-d-weight="medium" style="color: var(--color-text-success);" data-web-style="s46" data-web-output="budget-description">剩余 25K Tokens</p></div><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s32">教学用共享窗口预算模型；真实 API 可能另有独立的输出上限和计数规则。</span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">工程结论：</span> 上下文窗口是有限资源，聊天历史、RAG 文档和输出预算需要统一管理。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">二、为什么上下文没有超限，模型仍然可能遗漏信息？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">这是比 Token 上限更值得关注的问题。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">假设我们向模型输入一篇很长的文档：</p><div data-web-style="s47"><div data-web-style="s48"><div data-code-block="true" data-search-result-target="" data-web-style="s49" data-web-code=""><div data-web-style="s50"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s51" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s53">纯文本</div><div data-web-style="s54"><div data-code-block-controls="true" role="presentation" data-web-style="s55"><span data-web-style="s56"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s57" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s56"><button type="button" aria-label="复制代码" data-web-style="s57" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-code-block-source="true" dir="ltr" data-web-style="s60"><code data-web-style="s61"><span data-web-style="s62"><span data-web-style="s62">文档开头：公司介绍</span>
<span data-web-style="s62">...</span>
<span data-web-style="s62">文档中间：某个 API 的重要限制</span>
<span data-web-style="s62">...</span>
<span data-web-style="s62">文档结尾：使用示例</span></span></code></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">然后提问：</p><blockquote data-d-component="blockquote" data-web-style="s63"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">这个 API 有什么限制？</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s10">即使重要信息确实存在于上下文中，模型也不一定能够稳定地找到并使用它。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">这种现象与长上下文中的信息定位、注意力分配和训练分布等因素有关。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">相关研究常将一种典型现象称为 <span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">Lost in the Middle（中间信息遗失）</span>：某些模型对位于长上下文开头或结尾的信息表现较好，而对中间信息的利用较弱。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">但这不是所有模型、所有任务都必然遵循的规律。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s22">2.1 信息位置与利用效果示意</h3><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s23"><p data-d-text-flow="" data-d-component="text" data-d-weight="medium" data-web-style="s64">长上下文中不同位置的信息利用效果</p><img alt="" data-d-component="svg" decoding="async" style="aspect-ratio: auto 340 / 210; color: var(--color-text-prose); width: 100%;" src="data:image/svg+xml;charset=utf-8,%3Csvg%20font-family%3D%22-apple-system-body%2C%20ui-sans-serif%2C%20-apple-system%2C%20system-ui%2C%20%26quot%3BSegoe%20UI%26quot%3B%2C%20Helvetica%2C%20%26quot%3BApple%20Color%20Emoji%26quot%3B%2C%20Arial%2C%20sans-serif%2C%20%26quot%3BSegoe%20UI%20Emoji%26quot%3B%2C%20%26quot%3BSegoe%20UI%20Symbol%26quot%3B%22%20font-weight%3D%22400%22%20data-d-component%3D%22svg%22%20fill%3D%22currentColor%22%20style%3D%22color%3Argb(237%2C%20237%2C%20237)%22%20viewBox%3D%220%200%20340%20210%22%20width%3D%22100%25%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Cline%20x1%3D%2242%22%20y1%3D%2235%22%20x2%3D%22324%22%20y2%3D%2235%22%20stroke%3D%22currentColor%22%20opacity%3D%22.09%22%2F%3E%3Cline%20x1%3D%2242%22%20y1%3D%2275%22%20x2%3D%22324%22%20y2%3D%2275%22%20stroke%3D%22currentColor%22%20opacity%3D%22.09%22%2F%3E%3Cline%20x1%3D%2242%22%20y1%3D%22115%22%20x2%3D%22324%22%20y2%3D%22115%22%20stroke%3D%22currentColor%22%20opacity%3D%22.09%22%2F%3E%3Cline%20x1%3D%2242%22%20y1%3D%22155%22%20x2%3D%22324%22%20y2%3D%22155%22%20stroke%3D%22currentColor%22%20opacity%3D%22.09%22%2F%3E%3Cline%20x1%3D%2242%22%20y1%3D%2215%22%20x2%3D%2242%22%20y2%3D%22173%22%20stroke%3D%22currentColor%22%20opacity%3D%22.4%22%2F%3E%3Cline%20x1%3D%2242%22%20y1%3D%22173%22%20x2%3D%22324%22%20y2%3D%22173%22%20stroke%3D%22currentColor%22%20opacity%3D%22.4%22%2F%3E%3Cpath%20d%3D%22M45%2039%20C95%2040%20108%20134%20180%20139%20S263%2046%20320%2037%22%20stroke%3D%22%232563eb%22%20stroke-width%3D%223%22%20fill%3D%22none%22%2F%3E%3Ccircle%20cx%3D%2245%22%20cy%3D%2239%22%20r%3D%225%22%20fill%3D%22%232563eb%22%2F%3E%3Ccircle%20cx%3D%22180%22%20cy%3D%22139%22%20r%3D%225%22%20fill%3D%22%232563eb%22%2F%3E%3Ccircle%20cx%3D%22320%22%20cy%3D%2237%22%20r%3D%225%22%20fill%3D%22%232563eb%22%2F%3E%3Ctext%20x%3D%2245%22%20y%3D%22192%22%20font-size%3D%2211%22%20fill%3D%22currentColor%22%20text-anchor%3D%22middle%22%3E%E5%BC%80%E5%A4%B4%3C%2Ftext%3E%3Ctext%20x%3D%22180%22%20y%3D%22192%22%20font-size%3D%2211%22%20fill%3D%22currentColor%22%20text-anchor%3D%22middle%22%3E%E4%B8%AD%E9%97%B4%3C%2Ftext%3E%3Ctext%20x%3D%22316%22%20y%3D%22192%22%20font-size%3D%2211%22%20fill%3D%22currentColor%22%20text-anchor%3D%22middle%22%3E%E7%BB%93%E5%B0%BE%3C%2Ftext%3E%3Ctext%20x%3D%2249%22%20y%3D%2214%22%20font-size%3D%2210%22%20fill%3D%22currentColor%22%3E%E4%BF%A1%E6%81%AF%E5%88%A9%E7%94%A8%E6%95%88%E6%9E%9C%EF%BC%88%E7%A4%BA%E6%84%8F%EF%BC%89%3C%2Ftext%3E%3C%2Fsvg%3E" data-web-style="s65"><span data-d-text-flow="" data-d-component="caption" data-d-size="lg" data-d-weight="normal" data-web-style="s32">概念图，不是某个模型的实测准确率曲线。</span></div><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s22">2.2 如何解决？</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s19">工程上可以考虑：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0); gap: calc(var(--spacing, 0.25rem) * 0);" data-web-style="s12"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">先检索相关内容，而不是把所有文档直接塞给模型。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">使用语义切分与重排序，提高关键片段的相关性。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">对长文档分段提取事实，再进行汇总。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">为关键事实保留来源、位置与引用。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">使用专门的长上下文评估集测试不同位置的信息利用情况。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">上下文窗口越大，不等于模型对每一个位置的信息都利用得同样好。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">三、幻觉（Hallucination）：为什么 AI 会编造答案？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">假设你向聊天机器人提问：</p><blockquote data-d-component="blockquote" data-web-style="s63"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">React 19 是否提供 <code data-d-component="code" data-web-style="s66">useMagicState()</code> Hook？</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s10">模型可能生成：</p><div data-web-style="s47"><div data-web-style="s48"><div data-code-block="true" data-search-result-target="" data-web-style="s49" data-web-code=""><div data-web-style="s50"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s51" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s53">TypeScript</div><div data-web-style="s54"><div data-code-block-controls="true" role="presentation" data-web-style="s55"><span data-web-style="s56"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s57" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s56"><button type="button" aria-label="复制代码" data-web-style="s57" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s38"><div data-web-style="s67"><div dir="ltr" data-web-style="s68"><div data-web-style="s69"><pre data-web-style="s70"><code data-web-style="s62"><span data-web-style="s71">const</span><span data-web-style="s62"> [</span><span data-web-style="s72">value</span><span data-web-style="s62">, </span><span data-web-style="s72">setValue</span><span data-web-style="s62">] </span><span data-web-style="s71">=</span><span data-web-style="s62"> </span><span data-web-style="s72">useMagicState</span><span data-web-style="s62">(</span><span data-web-style="s73">0</span><span data-web-style="s62">);</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">然后解释这个 Hook 的用途。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">但这里的 <code data-d-component="code" data-web-style="s66">useMagicState()</code> 是一个人为虚构的 API 名称。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">如果模型把它当成 React 官方 API 介绍，就产生了事实性错误。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s22">3.1 为什么会发生？</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s19">回顾第一篇的核心原理：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">大语言模型通过学习数据中的模式来生成 Token，而不是在每次输出前自动执行事实核验。</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">它可能学会了大量类似代码的结构：</p><div data-web-style="s47"><div data-web-style="s48"><div data-code-block="true" data-search-result-target="" data-web-style="s49" data-web-code=""><div data-web-style="s50"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s51" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s53">TypeScript</div><div data-web-style="s54"><div data-code-block-controls="true" role="presentation" data-web-style="s55"><span data-web-style="s56"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s57" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s56"><button type="button" aria-label="复制代码" data-web-style="s57" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s38"><div data-web-style="s67"><div dir="ltr" data-web-style="s68"><div data-web-style="s69"><pre data-web-style="s70"><code data-web-style="s62"><span data-web-style="s71">const</span><span data-web-style="s62"> [</span><span data-web-style="s72">value</span><span data-web-style="s62">, </span><span data-web-style="s72">setValue</span><span data-web-style="s62">] </span><span data-web-style="s71">=</span><span data-web-style="s62"> </span><span data-web-style="s72">useState</span><span data-web-style="s62">(</span><span data-web-style="s73">0</span><span data-web-style="s62">);</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">因此，即使遇到不存在的 API 名称，也可能生成语法上合理、但事实不正确的解释。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s22">3.2 幻觉不只有一种</h3><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s77"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto;" data-web-style="s78"><tbody data-web-style="s79"><tr data-d-component="table-row" data-web-style="s80"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s81"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">类型</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s83"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">示例</p></th></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">事实幻觉</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">编造不存在的产品或历史事件</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">引用幻觉</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">编造论文标题、URL 或参考文献</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">代码幻觉</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">调用不存在的 API</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">上下文不一致</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">回答与用户提供的文档相矛盾</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">推理错误</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">中间步骤或最终结论不成立</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">要特别注意：<span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">模型表达得越自信，不代表答案越可靠。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">四、Temperature 设置为 0，能消除幻觉吗？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">不能。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">第 06 篇我们学过：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s20"><span data-web-style="s21"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>P</mi><mi>i</mi></msub><mo>=</mo><mi mathvariant="normal">softmax</mi><mo>⁡</mo><mo stretchy="false">(</mo><msub><mi>z</mi><mi>i</mi></msub><mi mathvariant="normal">/</mi><mi>T</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">P_i=\\operatorname{softmax}(z_i/T)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3117em;"><span style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mop"><span class="mord mathrm">softmax</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3117em;"><span style="top: -2.55em; margin-left: -0.044em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mord mathnormal" style="margin-right: 0.1389em;">T</span><span class="mclose">)</span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">Temperature 主要影响采样分布。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">低温度通常让输出更集中，但如果模型最倾向的答案本身就是错的，低温度也无法修正这个错误。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">例如：</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s77"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto;" data-web-style="s78"><tbody data-web-style="s79"><tr data-d-component="table-row" data-web-style="s80"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s81"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">候选回答</p></th><th data-d-align="end" data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s87"><p data-d-text-flow="" data-d-component="text" data-web-style="s88">模型偏好（假设）</p></th></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">错误答案 A</p></td><td data-d-align="end" data-d-component="table-cell" data-d-valign="start" data-web-style="s89"><p data-d-text-flow="" data-d-component="text" data-web-style="s90">75%</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">正确答案 B</p></td><td data-d-align="end" data-d-component="table-cell" data-d-valign="start" data-web-style="s89"><p data-d-text-flow="" data-d-component="text" data-web-style="s90">20%</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">其他答案</p></td><td data-d-align="end" data-d-component="table-cell" data-d-valign="start" data-web-style="s89"><p data-d-text-flow="" data-d-component="text" data-web-style="s90">5%</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">即使使用贪心解码，也可能选择错误答案 A。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">因此：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">降低随机性 ≠ 提高事实正确性。</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">解决幻觉通常需要结合检索、工具调用、结构化约束和结果验证。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">五、为什么大模型会在数学和逻辑推理中出错？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">大模型可以学习大量数学与逻辑模式，但生成流畅的解释，不代表每一步计算都正确。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">例如：</p><blockquote data-d-component="blockquote" data-web-style="s63"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">一个商品原价 100 元，先涨价 20%，再降价 20%，最后是不是又回到了 100 元？</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s10">正确答案是：</p><div data-d-block="" data-d-component="math" dir="ltr" data-web-style="s20"><span data-web-style="s21"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>100</mn><mo>×</mo><mn>1.2</mn><mo>×</mo><mn>0.8</mn><mo>=</mo><mn>96</mn></mrow><annotation encoding="application/x-tex">100\\times1.2\\times0.8=96</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord">100</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord">1.2</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">0.8</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">96</span></span></span></span></span></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">最终价格是 96 元，而不是 100 元。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">这种错误可能来自多个方面：错误地套用语言模式、遗漏中间条件、算术运算不准确，或者错误步骤在后续推理中被不断放大。</p><h3 data-d-text-flow="" data-d-component="title" data-d-size="md" data-d-weight="semibold" data-web-style="s22">5.1 为什么生成更多推理步骤也不一定正确？</h3><p data-d-text-flow="" data-d-component="text" data-web-style="s19">因为增加推理步骤并不自动保证每一步都有效。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">假设模型的某个中间步骤出现错误，后续步骤即使逻辑连贯，也可能建立在错误前提上。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">因此，对于确定性任务，我们通常应该使用外部工具。</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s77"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto;" data-web-style="s78"><tbody data-web-style="s79"><tr data-d-component="table-row" data-web-style="s80"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s81"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">任务</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s83"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">更可靠的方案</p></th></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">金额计算</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">计算器或代码执行</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">日期计算</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">日期库</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">数据库统计</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">SQL 查询</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">实时股票价格</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">可信行情接口</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">API 是否存在</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">官方文档与类型检查</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">工程结论：让 LLM 负责理解问题、规划任务，让确定性工具负责可验证的计算。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">六、RAG 能完全消除幻觉吗？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">不能，但 RAG 是降低知识性幻觉的重要手段之一。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">RAG（Retrieval-Augmented Generation，检索增强生成）的核心思想是：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">在生成答案前，先检索与问题相关的外部知识。</span></p><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s23"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">带证据验证的 RAG 流程</span></p><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: var(--color-surface-secondary);" data-web-style="s91"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">用户提出问题</span></p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s92"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-secondary); font-size: 16px;" data-web-style="s93" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s94"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: var(--color-surface-secondary);" data-web-style="s91"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">检索可信文档 + 重排序</span></p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s92"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-secondary); font-size: 16px;" data-web-style="s93" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s94"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: var(--color-surface-secondary); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: var(--color-surface-secondary);" data-web-style="s91"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">LLM 基于证据生成回答</span></p></div><div data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="center" data-web-style="s92"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" style="color: var(--color-text-secondary); font-size: 16px;" data-web-style="s93" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M12.707 18.707a1 1 0 0 1-1.414 0l-5-5a1 1 0 1 1 1.414-1.414L11 15.586V6a1 1 0 1 1 2 0v9.586l3.293-3.293a1 1 0 0 1 1.414 1.414l-5 5Z" clip-rule="evenodd" data-web-style="s94"></path></svg></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="--smoothing-background-color: rgba(22,163,74,0.09); border-radius: var(--radius-lg); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); background-color: rgba(22, 163, 74, 0.09);" data-web-style="s95"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">核验引用与结论；证据不足则拒答</span></p></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">但 RAG 仍然存在几个风险：</p><ul data-d-component="list" data-d-marker="bullet" data-d-marker-layout="native" style="--d-list-row-gap: calc(var(--spacing, 0.25rem) * 0); gap: calc(var(--spacing, 0.25rem) * 0);" data-web-style="s12"><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">检索阶段没有找到真正相关的文档。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">文档虽然相关，但包含过期或错误的信息。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">模型误读了检索内容。</p></div></div></li><li data-d-component="list-item" data-d-marker-layout="native" data-web-style="s13"><div data-web-style="s14"><div data-d-list-item-content="" data-web-style="s15"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">模型给出的引用不能支持它的结论。</p></div></div></li></ul><p data-d-text-flow="" data-d-component="text" data-web-style="s10">因此，生产级 RAG 不能只关注向量相似度，还需要评估检索相关性、引用支持程度和回答的事实正确性。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">七、TypeScript：如何让聊天机器人在证据不足时拒答？</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">假设我们正在开发一个企业内部 AI 助手。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">用户提问：</p><blockquote data-d-component="blockquote" data-web-style="s63"><p data-d-text-flow="" data-d-component="text" data-web-style="s16">统一登录 SDK 如何验证 Token？</p></blockquote><p data-d-text-flow="" data-d-component="text" data-web-style="s10">机器人会先检索 SDK 文档。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">我们可以设计一个简单的检索结果过滤函数：</p><div data-web-style="s47"><div data-web-style="s48"><div data-code-block="true" data-search-result-target="" data-web-style="s49" data-web-code=""><div data-web-style="s50"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s51" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg><div data-web-style="s53">TypeScript</div><div data-web-style="s54"><div data-code-block-controls="true" role="presentation" data-web-style="s55"><span data-web-style="s56"><button type="button" aria-label="启用自动换行" aria-pressed="false" data-web-style="s57" data-web-action="wrap-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span><span data-web-style="s56"><button type="button" aria-label="复制代码" data-web-style="s57" data-web-action="copy-code"><svg aria-hidden="true" focusable="false" height="20" width="20" xmlns="http://www.w3.org/2000/svg" data-web-style="s58" viewBox="0 0 20 20"><path d="M6 6h11v11H6zM3 3h10v3M3 3v10h3" fill="none" stroke="currentColor"></path></svg></button></span></div></div></div><div data-web-style="s38"><div data-web-style="s67"><div dir="ltr" data-web-style="s68"><div data-web-style="s69"><pre data-web-style="s70"><code data-web-style="s62"><span data-web-style="s62">
</span><span data-web-style="s71">type</span><span data-web-style="s62"> </span><span data-web-style="s72">Evidence</span><span data-web-style="s62"> </span><span data-web-style="s71">=</span><span data-web-style="s62"> {
  text: </span><span data-web-style="s72">string</span><span data-web-style="s62">;
  source: </span><span data-web-style="s72">string</span><span data-web-style="s62">;
  score: </span><span data-web-style="s72">number</span><span data-web-style="s62">;
};

</span><span data-web-style="s71">function</span><span data-web-style="s62"> </span><span data-web-style="s72">buildContext</span><span data-web-style="s62">(
  </span><span data-web-style="s72">items</span><span data-web-style="s62">: </span><span data-web-style="s72">Evidence</span><span data-web-style="s62">[],
  </span><span data-web-style="s72">threshold</span><span data-web-style="s62"> </span><span data-web-style="s71">=</span><span data-web-style="s62"> </span><span data-web-style="s73">0.75</span><span data-web-style="s62">
) {
  </span><span data-web-style="s71">const</span><span data-web-style="s62"> </span><span data-web-style="s72">accepted</span><span data-web-style="s62"> </span><span data-web-style="s71">=</span><span data-web-style="s62"> </span><span data-web-style="s72">items</span><span data-web-style="s71">.</span><span data-web-style="s62">filter(
    </span><span data-web-style="s72">item</span><span data-web-style="s62"> =&gt; </span><span data-web-style="s72">item</span><span data-web-style="s71">.</span><span data-web-style="s62">score </span><span data-web-style="s71">&gt;=</span><span data-web-style="s62"> </span><span data-web-style="s72">threshold</span><span data-web-style="s62">
  );

  </span><span data-web-style="s71">if</span><span data-web-style="s62"> (</span><span data-web-style="s72">accepted</span><span data-web-style="s71">.</span><span data-web-style="s62">length </span><span data-web-style="s71">===</span><span data-web-style="s62"> </span><span data-web-style="s73">0</span><span data-web-style="s62">) {
    </span><span data-web-style="s71">return</span><span data-web-style="s62"> {
      canAnswer: </span><span data-web-style="s73">false</span><span data-web-style="s62">,
      context: </span><span data-web-style="s96">""</span><span data-web-style="s62">,
      sources: [] </span><span data-web-style="s71">as</span><span data-web-style="s62"> </span><span data-web-style="s72">string</span><span data-web-style="s62">[]
    };
  }

  </span><span data-web-style="s71">return</span><span data-web-style="s62"> {
    canAnswer: </span><span data-web-style="s73">true</span><span data-web-style="s62">,
    context: </span><span data-web-style="s72">accepted</span><span data-web-style="s62">
      </span><span data-web-style="s71">.</span><span data-web-style="s62">map(</span><span data-web-style="s72">item</span><span data-web-style="s62"> =&gt; </span><span data-web-style="s72">item</span><span data-web-style="s71">.</span><span data-web-style="s62">text)
      </span><span data-web-style="s71">.</span><span data-web-style="s62">join(</span><span data-web-style="s96">"</span><span data-web-style="s97">\\n\\n</span><span data-web-style="s96">"</span><span data-web-style="s62">),
    sources: </span><span data-web-style="s72">accepted</span><span data-web-style="s71">.</span><span data-web-style="s62">map(
      </span><span data-web-style="s72">item</span><span data-web-style="s62"> =&gt; </span><span data-web-style="s72">item</span><span data-web-style="s71">.</span><span data-web-style="s62">source
    )
  };
}

</span><span data-web-style="s71">const</span><span data-web-style="s62"> </span><span data-web-style="s72">result</span><span data-web-style="s62"> </span><span data-web-style="s71">=</span><span data-web-style="s62"> </span><span data-web-style="s72">buildContext</span><span data-web-style="s62">([
  {
    text: </span><span data-web-style="s96">"统一登录 SDK 提供 token 校验方法"</span><span data-web-style="s62">,
    source: </span><span data-web-style="s96">"sdk.md"</span><span data-web-style="s62">,
    score: </span><span data-web-style="s73">0.91</span><span data-web-style="s62">
  }
]);

</span><span data-web-style="s72">console</span><span data-web-style="s71">.</span><span data-web-style="s62">log(</span><span data-web-style="s72">result</span><span data-web-style="s62">);
</span></code></pre></div></div></div></div></div></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">这个例子展示了一个基本原则：没有达到检索条件的证据时，不应直接把未经验证的内容当成确定事实输出。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">不过，<code data-d-component="code" data-web-style="s66">0.75</code> 只是教学阈值，并不是所有 Embedding 模型通用的可靠标准。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">实际生产环境还需要进行检索分数校准、多文档证据验证和答案质量评估。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">八、生产级聊天机器人的风险控制</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">结合我们前面学习的知识，可以整理出一张工程决策表。</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s77"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto;" data-web-style="s78"><tbody data-web-style="s79"><tr data-d-component="table-row" data-web-style="s80"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s81"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">风险</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s83"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">工程措施</p></th></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">编造不存在的 API</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">官方文档检索、代码编译和测试</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">长上下文遗漏信息</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">分段处理、检索与重排序</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">数值计算错误</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">计算器、代码执行工具</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">编造引用</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">引用溯源、证据支持评估</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">回答过度自信</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">允许拒答、表达不确定性</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">提示词注入</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">外部文本视为不可信数据、最小权限</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">这里还需要强调一个安全问题：</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">即使模型能够检索到某份企业文档，也不代表当前用户有权读取它。</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">例如，一个普通员工询问管理员后台的敏感信息，RAG 检索系统必须在数据访问层执行权限控制，而不是仅依靠 System Prompt 要求模型保密。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">九、本篇总结</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19">今天最重要的不是记住某个模型的上下文长度，而是理解模型能力的边界。</p><div data-d-column-sizing="auto" data-d-component="table" data-web-style="s77"><table data-d-column-sizing="auto" data-d-dividers="" style="table-layout: auto;" data-web-style="s78"><tbody data-web-style="s79"><tr data-d-component="table-row" data-web-style="s80"><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s81"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">概念</p></th><th data-d-component="table-cell" data-d-valign="start" scope="col" data-web-style="s83"><p data-d-text-flow="" data-d-component="text" data-web-style="s82">核心结论</p></th></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">Context Window</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">决定可处理的上下文容量</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">Lost in the Middle</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">长上下文中的信息利用可能不均衡</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">Hallucination</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">流畅生成不等于事实正确</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">Temperature</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">控制采样行为，不保证准确性</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">RAG</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">提供外部证据，但仍需要验证</p></td></tr><tr data-d-component="table-row" data-web-style="s80"><td data-d-component="table-cell" data-d-valign="start" data-web-style="s84"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">Tool Calling</p></td><td data-d-component="table-cell" data-d-valign="start" data-web-style="s86"><p data-d-text-flow="" data-d-component="text" data-web-style="s85">让确定性任务交给专门工具</p></td></tr></tbody></table></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">一个可靠的 AI 聊天机器人，不应该假设大模型永远正确，而应该在架构设计中主动考虑模型可能出错。</span></p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">十、交互式课后测验</h2><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 4);" data-web-style="s98"><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">1. 模型支持 128K 上下文，是否意味着可以输入 128K 再无限输出？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s100" data-web-question="0"><div data-d-component="radio" data-web-style="s101"><label for="0-_r_6d7_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-0" value="0" id="0-_r_6d7_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>可以</label></div><div data-d-component="radio" data-web-style="s101"><label for="1-_r_6d9_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-0" value="1" id="1-_r_6d9_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>不可以，通常需要统一预算且可能有独立限制</label></div><div data-d-component="radio" data-web-style="s101"><label for="2-_r_6db_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-0" value="2" id="2-_r_6db_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>只与网络速度有关</label></div></div></div><div data-d-component="divider" style="--divider-color: var(--color-border-subtle); --divider-size: 1px;" data-web-style="s105"></div><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">2. Lost in the Middle 描述的典型现象是什么？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s100" data-web-question="1"><div data-d-component="radio" data-web-style="s101"><label for="0-_r_6de_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-1" value="0" id="0-_r_6de_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>所有模型都完全忽略中间内容</label></div><div data-d-component="radio" data-web-style="s101"><label for="1-_r_6dg_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-1" value="1" id="1-_r_6dg_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>部分模型对长上下文中间信息的利用较弱</label></div><div data-d-component="radio" data-web-style="s101"><label for="2-_r_6di_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-1" value="2" id="2-_r_6di_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>中间的 Token 不参与 Attention</label></div></div></div><div data-d-component="divider" style="--divider-color: var(--color-border-subtle); --divider-size: 1px;" data-web-style="s105"></div><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">3. Temperature 设置为 0，是否能消除幻觉？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s100" data-web-question="2"><div data-d-component="radio" data-web-style="s101"><label for="0-_r_6dl_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-2" value="0" id="0-_r_6dl_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>能</label></div><div data-d-component="radio" data-web-style="s101"><label for="1-_r_6dn_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-2" value="1" id="1-_r_6dn_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>不能</label></div><div data-d-component="radio" data-web-style="s101"><label for="2-_r_6dp_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-2" value="2" id="2-_r_6dp_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>会自动连接互联网</label></div></div></div><div data-d-component="divider" style="--divider-color: var(--color-border-subtle); --divider-size: 1px;" data-web-style="s105"></div><div data-d-component="box" data-d-direction="col" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s99"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">4. 企业知识库问答要降低幻觉，应该优先考虑什么？</span></p><div role="radiogroup" aria-required="false" data-direction="col" aria-label="Options" data-d-component="radio-group" style="outline: none;" data-web-style="s100" data-web-question="3"><div data-d-component="radio" data-web-style="s101"><label for="0-_r_6ds_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-3" value="0" id="0-_r_6ds_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>RAG、引用溯源和验证</label></div><div data-d-component="radio" data-web-style="s101"><label for="1-_r_6du_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-3" value="1" id="1-_r_6du_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>只增加最大输出长度</label></div><div data-d-component="radio" data-web-style="s101"><label for="2-_r_6e0_" data-web-style="s102"><div data-web-style="s103"><input type="radio" name="web-lesson-7-question-3" value="2" id="2-_r_6e0_" style="appearance:auto;width:16px;height:16px;margin:0;accent-color:var(--vp-c-brand-1);cursor:pointer"></div>关闭所有日志</label></div></div></div><div data-d-component="row" data-d-direction="row" style="gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s106"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" style="flex: 1 1 0%;" data-web-style="s14"><button type="button" data-color="primary" data-variant="solid" data-pill="" data-size="lg" data-block="" data-d-component="button" data-d-block="" data-web-style="s107" data-web-action="submit-quiz"><span data-web-style="s108">提交评分</span></button></div><button type="button" data-color="secondary" data-variant="outline" data-pill="" data-size="lg" data-d-component="button" data-web-style="s109" data-web-action="reset-quiz"><span data-web-style="s110">重新作答</span></button></div></div><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">十一、学习疑问与解答</h2><p data-d-text-flow="" data-d-component="text" data-web-style="s19"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">Q1：上下文窗口越大，回答一定越准确吗？</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">不一定。更长的上下文可能提供更多证据，也可能引入更多噪声和信息定位困难。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">Q2：Temperature 为 0，回答就完全确定吗？</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">不一定。较低随机性不保证事实正确，服务端计算实现和模型版本变化也可能造成差异。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">Q3：RAG 和微调哪个更适合更新企业知识？</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">通常优先考虑 RAG，因为知识可以持续更新，并保留来源。微调更适合改善模型在特定任务上的行为和表现。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">Q4：如果模型说「我非常确定」，能当作真实置信度吗？</span></p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">不能直接当作经过校准的概率。仍需要独立评估和外部证据验证。</p><div data-d-component="divider" style="--divider-color: var(--color-border); --divider-size: 1px;" data-web-style="s17"></div><h2 data-d-text-flow="" data-d-component="title" data-d-size="lg" data-d-weight="semibold" data-web-style="s18">第 07 篇已提交 GitHub</h2><div data-color="success" data-size="sm" data-pill="" data-variant="soft" data-d-component="badge" data-d-weight="medium" data-web-style="s111"><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-d-inline="" style="display: inline-block; vertical-align: calc(0.5cap - 0.5em);" data-web-style="s112" viewBox="0 0 24 24"><path d="M12 4C7.58172 4 4 7.58172 4 12C4 16.4183 7.58172 20 12 20C16.4183 20 20 16.4183 20 12C20 7.58172 16.4183 4 12 4ZM2 12C2 6.47715 6.47715 2 12 2C17.5228 2 22 6.47715 22 12C22 17.5228 17.5228 22 12 22C6.47715 22 2 17.5228 2 12ZM16.0755 7.93219C16.5272 8.25003 16.6356 8.87383 16.3178 9.32549L11.5678 16.0755C11.3931 16.3237 11.1152 16.4792 10.8123 16.4981C10.5093 16.517 10.2142 16.3973 10.0101 16.1727L7.51006 13.4227C7.13855 13.014 7.16867 12.3816 7.57733 12.0101C7.98598 11.6386 8.61843 11.6687 8.98994 12.0773L10.6504 13.9039L14.6822 8.17451C15 7.72284 15.6238 7.61436 16.0755 7.93219Z" fill="currentColor" data-web-style="s113"></path></svg><span data-web-style="s114"> 源码提交成功</span></div><div data-d-component="box" data-d-direction="col" data-d-has-border="" style="border: 1px solid var(--color-border); border-radius: var(--radius-xl); --w-box-gutter-block-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-block-start: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-end: calc(var(--spacing, 0.25rem) * 3); --w-box-gutter-inline-start: calc(var(--spacing, 0.25rem) * 3); padding-block: calc(var(--spacing, 0.25rem) * 3); padding-inline: calc(var(--spacing, 0.25rem) * 3); gap: calc(var(--spacing, 0.25rem) * 2);" data-web-style="s23"><p data-d-text-flow="" data-d-component="text" data-web-style="s24"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">第 07 篇 · 大模型的能力边界</span></p><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s33">已包含教程正文、上下文预算模拟器、长上下文 SVG 示意图、TypeScript 示例、4 道交互式选择题和学习疑问解答。</p><button type="button" data-color="primary" data-variant="solid" data-pill="" data-size="lg" data-block="" data-d-component="button" data-d-block="" data-web-style="s115"><span data-web-style="s116"><span data-web-style="s117">阅读 GitHub Pages 文章 </span><svg width="1em" height="1em" fill="currentColor" data-d-component="icon" data-d-inline="" style="display: inline-block; vertical-align: calc(0.5cap - 0.5em);" data-web-style="s118" viewBox="0 0 24 24"><path fill-rule="evenodd" d="M15 5a1 1 0 1 1 0-2h5a1 1 0 0 1 1 1v5a1 1 0 1 1-2 0V6.414l-5.293 5.293a1 1 0 0 1-1.414-1.414L17.586 5H15ZM4 7a3 3 0 0 1 3-3h3a1 1 0 1 1 0 2H7a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1v-3a1 1 0 1 1 2 0v3a3 3 0 0 1-3 3H7a3 3 0 0 1-3-3V7Z" clip-rule="evenodd" data-web-style="s119"></path></svg></span></button><button type="button" data-color="secondary" data-variant="outline" data-pill="" data-size="lg" data-block="" data-d-component="button" data-d-block="" data-web-style="s109"><span data-web-style="s110">查看最新 GitHub 提交</span></button></div><div data-d-align="center" data-d-auto-spacing="" data-d-component="row" data-d-direction="row" data-d-justify="between" data-web-style="s120"><p data-d-text-flow="" data-d-component="text" data-d-size="sm" style="color: var(--color-text-secondary);" data-web-style="s33">学习进度：7 / 40 篇</p><p data-d-text-flow="" data-d-component="text" data-web-style="s37"><span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">17.5%</span></p></div><div data-d-auto-spacing="" data-d-clip="true" data-d-component="box" data-d-direction="col" data-d-has-height="" style="--smoothing-background-color: var(--color-surface-tertiary); border-radius: 9999px; background-color: var(--color-surface-tertiary); flex-shrink: 0; height: 8px;" data-web-style="s121"><div data-d-auto-spacing="" data-d-component="box" data-d-direction="col" data-d-has-width="" data-d-has-height="" style="--smoothing-background-color: rgba(22,163,74,0.85); border-radius: 9999px; background-color: rgba(22, 163, 74, 0.85); flex-shrink: 0; height: 100%; width: 17.5%;" data-web-style="s122"></div></div><p data-d-text-flow="" data-d-component="text" data-web-style="s10">本次 GitHub 文章已包含完整的知识主题，但部分文字和代码的组织与聊天版仍有差异，<span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">尚未达到严格的逐项 1:1 验收</span>；GitHub Actions 构建与 Pages 实际部署也尚未验证。</p><p data-d-text-flow="" data-d-component="text" data-web-style="s10">下一篇是 <span data-d-text-flow="" data-d-component="text" data-d-default-strong="" data-d-inline="" data-web-style="s11">第 08 篇《Prompt 与 Messages：聊天机器人如何理解用户指令？》</span>，我们将正式进入第二阶段——聊天机器人核心原理。</p></div></div></div></div></div></section>`,o=7,p=[{answer:1,explanation:"输入、输出和消息开销都可能占用上下文预算，具体规则取决于模型 API。"},{answer:1,explanation:"这是在部分模型和任务中观察到的现象，并不是绝对规律。"},{answer:1,explanation:"降低随机性不能修正模型本身偏好的错误事实。"},{answer:0,explanation:"检索可靠证据、核验引用和允许拒答，比单纯修改采样参数更有针对性。"}],t={chapter:o,questions:p};const y=JSON.parse('{"title":"07 · 大模型的能力边界：上下文窗口、幻觉与推理限制","description":"","frontmatter":{"title":"07 · 大模型的能力边界：上下文窗口、幻觉与推理限制","outline":"deep","readingTime":"15","courseMeta":false},"headers":[],"relativePath":"guide/ai/chatbot-course/07-model-limitations.md","filePath":"guide/ai/chatbot-course/07-model-limitations.md","lastUpdated":1792998910000}'),i={name:"guide/ai/chatbot-course/07-model-limitations.md"},v=Object.assign(i,{setup(r){return(c,b)=>(d(),s("div",null,[n(e,{source:a(l),chapter:a(t).chapter,questions:a(t).questions},null,8,["source","chapter","questions"])]))}});export{y as __pageData,v as default};
